function normalizeDomain(value) {
  if (!value) return '';
  try {
    const url = new URL(String(value).startsWith('http') ? String(value) : `https://${value}`);
    return url.hostname.replace(/^www\./i, '').toLowerCase();
  } catch {
    return '';
  }
}

const website = $json.Website || $json.website || '';
const normalizedDomain = normalizeDomain(website);

return {
  json: {
    ...$json,
    normalizedDomain,
    enrichmentSkipped: !normalizedDomain,
    enrichmentSkipReason: normalizedDomain ? '' : 'missing_or_invalid_domain'
  }
};

const normalizedItems = $('Normalize Candidate Domain').all();
const byRecord = new Map();

function scoreCandidate(email) {
  const type = String(email.type || '').toLowerCase();
  const value = String(email.value || email.email || '').toLowerCase();
  const confidence = Number(email.confidence || email.score || 0);
  let score = confidence;
  if (type === 'generic') score += 15;
  if (/^(info|admin|hello|sales|office|contact)@/.test(value)) score += 10;
  if (/gmail\.com|outlook\.com|hotmail\.com|yahoo\.com/.test(value)) score -= 50;
  return score;
}

for (const item of items) {
  if (item.json?.error) continue;
  const sourceIndex = Array.isArray(item.pairedItem)
    ? item.pairedItem[0]?.item
    : item.pairedItem?.item;
  const original = normalizedItems[sourceIndex ?? 0]?.json;
  if (!original?.id) continue;

  const candidate = item.json || {};
  const value = String(candidate.value || candidate.email || '').trim().toLowerCase();
  if (!value || !value.includes('@')) continue;

  const existing = byRecord.get(original.id);
  const scored = { original, candidate, value, score: scoreCandidate(candidate) };
  if (!existing || scored.score > existing.score) byRecord.set(original.id, scored);
}

return [...byRecord.values()].map(({ original, candidate, value }) => {
  const sources = Array.isArray(candidate.sources) ? candidate.sources : [];
  const sourceUri = sources[0]?.uri || sources[0]?.domain || '';
  const confidence = candidate.confidence || candidate.score || '';
  const note = [
    `Hunter enrichment ${new Date().toISOString()}`,
    `Domain: ${original.normalizedDomain}`,
    confidence !== '' ? `Confidence: ${confidence}` : '',
    candidate.type ? `Type: ${candidate.type}` : '',
    sourceUri ? `Source: ${sourceUri}` : '',
    'Review required before Ready to Email. This workflow does not establish consent.'
  ].filter(Boolean).join('\n');

  return {
    json: {
      id: original.id,
      Email: value,
      Status: 'Email Found',
      Notes: note
    }
  };
});
